GUIDE_FOLLOWUP_NOTES = {
    "share-your-result": ("分享後的四十八小時", "分享結束後不要立刻追問對方是否完全認同。先記下對方實際重述的內容、哪一句讓氣氛放鬆，以及哪個請求仍不清楚。四十八小時內只追蹤原先約定的小行動，不把沉默解讀成拒絕，也不以再次轉傳結果施壓。若對方提出自己的偏好，先用同一套觀察、感受、需求與請求格式確認，讓兩人的資料具有相同份量。"),
    "repair-after-conflict": ("修復完成的判斷方式", "一次道歉說完不代表修復完成。真正可觀察的是：承諾的行動是否在約定時間內發生、同類事件再出現時是否更早暫停，以及受影響的人能否不用再次證明痛苦就被聽見。回看時只核對本次承諾，不要求立即恢復親密。若承諾反覆失效，應縮小行動或重新評估雙方是否有共同修復意願。"),
    "words-of-affirmation-scripts": ("判斷肯定是否被收到", "說完後觀察對方是否能自然接話，而不是只看他有沒有說謝謝。有些人會害羞、沉默或轉移話題，仍可能收到心意；可以稍後問偏好口頭、文字、公開或私下哪一種形式。若對方表示壓力，就降低頻率並停止要求正面反應。肯定的品質來自準確觀察，不以回報、親密或服從作為交換。"),
    "acts-of-service-boundaries": ("兩週後的分工追蹤", "分工調整後，用兩週檢查一次完整任務是否真的轉移，包括發現、安排、執行與收尾。若新負責者需要學習，不要默認原負責者繼續提醒所有細節；可以先約定一次交接與可查閱清單。追蹤重點是可持續性，不是抓錯。有人暫時無法承擔時，也要寫明替代安排與結束日期，避免救急默認成永久責任。"),
    "gifts-are-not-materialism": ("收下之後仍保有選擇", "禮物送出後，收禮者仍可決定使用、轉送、退換或不公開展示。送禮者可以失落，但不能用價格、準備時間或驚喜程度要求特定反應。若雙方對保存物品的期待不同，事前談空間、預算與處理方式。真正需要追蹤的是對方是否感到被記得，而不是物品是否永久留在視線中。"),
    "quality-time-long-distance": ("每月校準遠距節奏", "月底各自回答哪次連結最有在場感、哪次安排造成等待，以及下月有哪些工作或時差變化。只調整一個參數，例如頻率、長度或活動形式，保留其他穩定元素，才看得出改動是否有效。若連續多次無法履約，先承認目前容量，不以更多承諾安撫焦慮；可降低頻率並把改約規則寫得更清楚。"),
    "physical-touch-consent-safety": ("接觸偏好的定期更新", "身體狀況、壓力、藥物、創傷反應與關係經驗都可能改變接觸偏好。可在沒有親密行動正在發生時更新接觸地圖，避免把詢問放在難以拒絕的當下。任何標記都只是目前資訊，不是未來同意。若一方不想說明原因，仍應尊重停止；理解可以延後，停止不能延後。"),
    "weekly-relationship-review": ("讓回顧不變成監控", "回顧表只保存完成對話所需的最少內容，不記錄用來威脅、公開或證明誰比較有問題的細節。每四週一起決定哪些紀錄可以刪除，並確認雙方都能查看與停止使用。若有人因表格感到被評分，可改為口頭各說一件保留與一件調整，不必為了維持流程而犧牲安全感。回顧缺席一次不代表關係失敗；先確認是否疲累、時間不合或議題過重，再共同決定改期或縮短。"),
    "emotional-needs-checklist": ("提出請求後的自我照顧", "請求可能被拒絕、延後或修改，因此開口前先準備一個不依賴對方立即配合的安定方式，例如散步、聯絡朋友、調整環境或延後重要決定。這不是假裝不需要關係，而是避免把所有調節責任放在同一個人身上。事後記錄哪個需要仍存在，再選擇新的策略或更合適的支援來源。"),
    "misfrequency-examples": ("驗證翻譯是否真的改善", "選定替代方式後，只試一至兩次並詢問實際感受。不要因對方沒有立刻感動就判定方法失敗，也不要一次更換時間、形式與內容，否則無法知道哪個差異有幫助。若雙方仍收到不同訊號，回到事件與界線重新確認；分類只是提出問題的工具，不是要求對方適應的答案。"),
    "relationship-stages": ("階段轉換時重新取得共識", "從曖昧到交往、同住、遠距或分開，都應重新談聯絡、隱私、時間與身體界線，不沿用前一階段的默認。測驗結果可以作為其中一個話題，但不能代替關係定義。若雙方對階段理解不同，先把目前承諾與可期待行為寫清楚，再決定哪些愛的表達適合現在。任何一方都可在新階段提出較慢節奏；不同意加深承諾，不等於否定先前所有在乎。每次轉換後約一個回看日期，確認原先安排仍符合彼此生活。"),
    "healthy-boundaries": ("界線提出後觀察行為", "健康回應不一定是立刻同意，而是願意停止當下越界、詢問細節並在之後協商。需要留意的不是一次失望，而是持續嘲諷界線、刻意試探、聯合他人施壓或在你執行保護行動後報復。把事件日期與可觀察行為留給自己，不必用長篇辯論說服對方承認；安全與自主不以對方認同為前提。"),
}
